import { useState, useEffect } from "react";

function App() {
  const [entities, setEntities] = useState([]);
  const [input, setInput] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editInput, setEditInput] = useState("");

  useEffect(() => {
    fetch("/api/entities")
      .then(res => res.json())
      .then(data => setEntities(data));
  }, []);

  // Add
  const handleAdd = () => {
    if (!input.trim()) return;

    fetch("/api/entities", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: input, body: "" })
    })
      .then(res => res.json())
      .then(newEntity => {
        setEntities(prev => [...prev, newEntity]);
        setInput("");
      });
  };

  // Delete
  const handleDelete = (id) => {
    fetch(`/api/entities/${id}`, { method: "DELETE" })
      .then(() => {
        setEntities(prev => prev.filter(e => e.id !== id));
      });
  };

  // Start editing
  const handleEdit = (entity) => {
    setEditingId(entity.id);
    setEditInput(entity.title);
  };

  // Save edit
  const handleSave = (id) => {
    fetch(`/api/entities/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: editInput, body: "" })
    })
      .then(res => res.json())
      .then(updated => {
        setEntities(prev => prev.map(e => e.id === id ? updated : e));
        setEditingId(null);
        setEditInput("");
      });
  };

  return (
    <div>
      <div>
        <input
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="Enter title"
        />
        <button onClick={handleAdd}>Add</button>
      </div>

      <ul>
        {entities.map(entity => (
          <li key={entity.id}>
            {editingId === entity.id ? (
              <>
                <input
                  value={editInput}
                  onChange={e => setEditInput(e.target.value)}
                />
                <button onClick={() => handleSave(entity.id)}>Save</button>
                <button onClick={() => setEditingId(null)}>Cancel</button>
              </>
            ) : (
              <>
                {entity.title}
                <button onClick={() => handleEdit(entity)}>Edit</button>
                <button onClick={() => handleDelete(entity.id)}>Delete</button>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
